import{_ as D,l as n,o as e,c as s,v as r,p as d,x as t,d as l,i,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"DDR 协议与命令","description":"","frontmatter":{"title":"DDR 协议与命令","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ddr-protocol.md","filePath":"cs/ddr-protocol.md","lastUpdated":1789023840000}'),p={name:"cs/ddr-protocol.md"};function c(A,a,R,h,_,B){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="ddr-协议与命令" tabindex="-1">DDR 协议与命令 <a class="header-anchor" href="#ddr-协议与命令" aria-label="Permalink to &quot;DDR 协议与命令&quot;">​</a></h1><div class="epigraph"><p>命令/地址在时钟边沿进颗粒，数据在 DQS 双边沿进出：ACT、RD、WR、PRE、REF 是有最小间隔的序列，不是随意的 SRAM 读写脉冲。</p><footer>—— 据 JEDEC DDR SDRAM 规范；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/row-buffer-bank-conflict">上一课</a>用状态机语言讲了命中与冲突。缺口是 <strong>DDR 协议</strong>：双倍数据速率、DQS 选通、命令编码与必须遵守的间隔，把控制器从「发读写」落实到引脚级合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SDR 每周期一次数据；DDR 在时钟升降沿都传（再后代 DDR2/3/4/5 速率与 bank 组不同，命令集同族）。命令：ACT（行地址）、RD/WR（列地址、突发）、PRE、REF、ZQ 校准等。缺口不是再定义行缓冲，而是：<strong>非法命令序列</strong>会导致不确定数据，STA 式的「最小周期」在这里变成 \\(t_{RCD}\\)、\\(t_{RAS}\\)、\\(t_{WR}\\)、\\(t_{RFC}\\) 一串。</p><p>校准：写均衡、读 DQS 训练，PHY 的模拟活，数字控制器假定训练完成。本课承认 PHY 存在，不设计均衡器——避免滑进模拟/光刻。</p><h3 id="ddr-不是「总线频率的两倍就结束」" tabindex="-1">DDR 不是「总线频率的两倍就结束」 <a class="header-anchor" href="#ddr-不是「总线频率的两倍就结束」" aria-label="Permalink to &quot;DDR 不是「总线频率的两倍就结束」&quot;">​</a></h3><p>有效带宽还受突发间隙、刷新、命令带宽、bank 冲突限制。把标称 MT/s 直接当应用程序 memcpy 带宽，阿姆达尔在内存墙上会失望。ECC 颗粒占用部分宽度或另宽。</p><p><span class="marginnote">JEDEC 各代 DDR 标准是本课主文献。CA:AQA 把命令与时序接到控制器。本课不背引脚表，钉命令与双边沿数据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>控制器维护每 bank 计时器：上次 ACT/RD 之后能否再发。命令/地址复用或按代分开。数据突发 BL8 对齐 cache 行常见。电源：自刷新在休眠时由颗粒内部刷新，对照组成<a href="/cs/dram-refresh">刷新课</a>的控制器义务转移。</p>',11)),(e(),d(E,null,{default:t(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MC%5B%22%E5%86%85%E5%AD%98%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%20--%3E%20CMD%5B%22CK%20%E4%B8%8A%E7%9A%84%20ACT%2FRD%2FWR%2FPRE%2FREF%22%5D%0A%20%20CMD%20--%3E%20DRAM%5B%22%E9%A2%97%E7%B2%92%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20DRAM%20--%3E%20DQ%5B%22DQS%20%E5%8F%8C%E8%BE%B9%E6%B2%BF%E6%95%B0%E6%8D%AE%22%5D%0A%20%20DQ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%9C%B0%E5%9D%80%E5%A6%82%E4%BD%95%E5%88%87%E5%88%B0%E8%BF%99%E4%BA%9B%E5%91%BD%E4%BB%A4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>LPDDR 面向移动，命令与电压不同，层次仍是 bank/行。本课以 JEDEC DDR 为轴。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>地址映射把物理地址拆成通道、rank、bank、行、列，然后才变成这些命令。调度器选择下一合法命令。HBM 用类似命令集、不同封装。本课把「引脚协议」交清。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 GDDR 的伪通道全部差异，不把 DIMM 金手指机械写成主体。不讨论内存超频社区。不把 Transformer 权重搬迁带宽当案例。</p><p>后课默认：访存是受时序约束的命令序列；数据在 DQS 上 DDR 传送。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DDR：命令在 CK，数据在 DQS 双边沿。</li><li>ACT/RD/WR/PRE/REF 带最小间隔；非法序列无定义。</li><li>标称速率 ≠ 应用带宽。</li><li>出处：JEDEC DDR；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const f=D(p,[["render",c]]);export{m as __pageData,f as default};
